    00: dest <- (SRC1[31] << 31) OR (TMP[30:0]);// Preserve Src1 sign bit
    01: dest <- TMP[31:0];// Preserve sign of compare result
    10: dest <- (0 << 31) OR (TMP[30:0]);// Zero out sign bit
    11: dest <- (1 << 31) OR (TMP[30:0]);// Set the sign bit
